dashboard.definition:
{
  "title": "Run Performance",
  "description": "Compare like runs by distance and terrain. Pace is distance-weighted. Best efforts are derived from continuous time-distance streams and include elapsed pause time. Year grain uses snapshot history; Comparable YTD ends at the import calendar date. Empty charts mean no eligible data in the selection. Automatic selects the first available metric; invalid bookmarked IDs show an explicit unavailable state. Availability is snapshot-wide and refreshes every five minutes.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.line",
      "title": "$performance_metadata:result.title$",
      "dataSources": {
        "primary": "performance_chart"
      },
      "options": {
        "nullValueDisplay": "gaps",
        "yAxisTitleText": "$performance_metadata:result.unit$",
        "xAxisTitleText": "Period"
      },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.table",
      "title": "Best efforts by target distance \u00b7 elapsed seconds",
      "dataSources": {
        "primary": "table_1"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.table",
      "title": "Comparable runs / annual coverage",
      "dataSources": {
        "primary": "table_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "training_lens",
            "dashboard": "activity_detail",
            "tokens": [
              {
                "token": "activity_id",
                "value": "row.activity_id.value"
              },
              {
                "token": "snapshot",
                "value": "row.snapshot_id.value"
              }
            ],
            "newTab": false
          }
        }
      ]
    }
  },
  "dataSources": {
    "dimensions": {
      "type": "ds.search",
      "name": "dimensions",
      "options": {
        "query": "| inputlookup training_lens_dimension_options | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "sport_options": {
      "type": "ds.chain",
      "name": "sport_options",
      "options": {
        "query": "| where dimension=\"sport\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "gear_options": {
      "type": "ds.chain",
      "name": "gear_options",
      "options": {
        "query": "| where dimension=\"gear\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "metric_options": {
      "type": "ds.search",
      "name": "metric_options",
      "options": {
        "query": "| inputlookup training_lens_metric_availability | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | where sport=$sport|s$ AND gear=$gear|s$ AND valid_count>0 AND metric_id IN (\"distance\",\"pace\",\"speed\",\"cadence\",\"avg_hr\") | lookup training_lens_metric_catalog metric_id OUTPUT label sort_order prerequisite | where coalesce(prerequisite,\"\")!=\"confirmed_cadence\" OR $cadence_units|s$!=\"Unconfirmed\" | stats first(label) AS label first(sort_order) AS sort_order max(refreshed_at) AS refreshed_at BY metric_id | eval label=if(now()-refreshed_at>900,label.\" \u00b7 cache stale\",label) | append [ | makeresults | eval metric_id=\"__auto__\",label=\"Automatic / first available\",sort_order=-1 ] | sort 0 sort_order metric_id",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "performance_options": {
      "type": "ds.chain",
      "name": "performance_options",
      "options": {
        "query": "| where metric_id=\"__auto__\" OR metric_id IN (\"distance\",\"pace\",\"speed\",\"cadence\",\"avg_hr\")",
        "extend": "metric_options"
      }
    },
    "performance_metadata": {
      "type": "ds.chain",
      "name": "performance_metadata",
      "options": {
        "query": "| where metric_id!=\"__auto__\" AND ($performance|s$=\"__auto__\" OR metric_id=$performance|s$) | head 1 | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),title=label.\" (\".unit.\")\" | appendpipe [ stats count | where count=0 | eval metric_id=\"__none__\",unit=\"\",title=\"Choose an available metric \u00b7 cache pending or selection unavailable\" ] | fields metric_id title unit",
        "extend": "performance_options",
        "enableSmartSources": true
      }
    },
    "performance_aggregate": {
      "type": "ds.search",
      "name": "performance_aggregate",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where sport=\"Run\" | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | eval metric_id=$performance_metadata:result.metric_id|s$ | eval eligible=case(metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,0),metric_id=\"pace\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,1,0),metric_id=\"speed\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,1,0),metric_id=\"cadence\",if(sport=\"Run\" AND average_cadence>0 AND duration_valid=1 AND moving_time_s>0 AND $cadence_units|s$!=\"Unconfirmed\",1,0),metric_id=\"avg_hr\",if(average_hr>0 AND average_hr<=255 AND duration_valid=1 AND moving_time_s>0,1,0)),numerator=case(metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),distance_m,null()),metric_id=\"pace\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,moving_time_s,null()),metric_id=\"speed\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,distance_m,null()),metric_id=\"cadence\",if(sport=\"Run\" AND average_cadence>0 AND duration_valid=1 AND moving_time_s>0 AND $cadence_units|s$!=\"Unconfirmed\",average_cadence*if($cadence_units|s$=\"Strides/min\",2,1)*moving_time_s,null()),metric_id=\"avg_hr\",if(average_hr>0 AND average_hr<=255 AND duration_valid=1 AND moving_time_s>0,average_hr*moving_time_s,null())),denominator=case(metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,null()),metric_id=\"pace\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,distance_m,null()),metric_id=\"speed\",if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,moving_time_s,null()),metric_id=\"cadence\",if(sport=\"Run\" AND average_cadence>0 AND duration_valid=1 AND moving_time_s>0 AND $cadence_units|s$!=\"Unconfirmed\",moving_time_s,null()),metric_id=\"avg_hr\",if(average_hr>0 AND average_hr<=255 AND duration_valid=1 AND moving_time_s>0,moving_time_s,null())) | eval bucket=case($grain|s$=\"Year\",coalesce(local_year,strftime(timestamp,\"%Y\")),$grain|s$=\"Month\",coalesce(local_month,strftime(timestamp,\"%Y-%m\")),true(),coalesce(local_week_start,strftime(relative_time(timestamp,\"@w1\"),\"%Y-%m-%d\"))),series=case(metric_id=\"zones\",\"Zone \".zone,metric_id IN (\"pace\",\"speed\") AND $sport|s$=\"All\",coalesce(sport,\"Unspecified\").if($split|s$=\"Gear\",\" \u00b7 \".coalesce(gear,\"Unspecified\"),\"\"),$split|s$=\"Sport\",coalesce(sport,\"Unspecified\"),$split|s$=\"Gear\",coalesce(gear,\"Unspecified\"),true(),\"Selected activities\") | stats sum(numerator) AS numerator sum(denominator) AS denominator max(numerator) AS peak median(numerator) AS midpoint avg(numerator) AS average dc(eval(if(eligible=1,local_date,null()))) AS days sum(eligible) AS valid_count count AS total_count BY bucket series metric_id | eval value=case(metric_id=\"distance\",if(valid_count>0,numerator,null()),metric_id=\"pace\",if(denominator>0,numerator/denominator,null()),metric_id=\"speed\",if(denominator>0,numerator/denominator,null()),metric_id=\"cadence\",if(denominator>0,numerator/denominator,null()),metric_id=\"avg_hr\",if(denominator>0,numerator/denominator,null())) | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit metric_factor imperial_factor precision | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),value=round(value*if($units|s$=\"Imperial\",imperial_factor,metric_factor),precision),coverage=if(total_count>0,100*valid_count/total_count,null()),series_label=series.\" \u00b7 \".label.\" (\".unit.\")\" | fields bucket series_label value unit coverage | sort 0 bucket series_label",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "performance_chart": {
      "type": "ds.chain",
      "name": "performance_chart",
      "options": {
        "query": "| xyseries bucket series_label value | appendpipe [ where $grain|s$=\"Year\" | makecontinuous bucket span=1 | eval _expanded=1 ] | where $grain|s$!=\"Year\" OR _expanded=1 | fields - _expanded",
        "extend": "performance_aggregate"
      }
    },
    "effort_options": {
      "type": "ds.chain",
      "name": "effort_options",
      "options": {
        "query": "| where dimension=\"effort_target\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All recorded targets\" ]",
        "extend": "dimensions"
      }
    },
    "table_1": {
      "type": "ds.search",
      "name": "table_1",
      "options": {
        "query": "index=strava sourcetype=training_lens:best_effort earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND stream_revision_id!=\"\" | fields stream_revision_id | appendpipe [ stats count | where count=0 | eval stream_revision_id=\"__none__\" ] | fields stream_revision_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where $effort_target|s$=\"All\" OR tostring(target_m)=$effort_target|s$ | stats min(duration_s) AS elapsed_seconds BY target_m | sort target_m",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "table_2": {
      "type": "ds.search",
      "name": "table_2",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($run_details|s$=\"Comparable runs\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where sport=\"Run\" AND pace_valid=1 | eval distance_km=round(distance_m/1000,2), pace_min_km=round(pace_min_km,2) | table activity_id snapshot_id local_date distance_km pace_min_km average_hr elevation_gain_m grade_adjusted_pace | where $run_details|s$=\"Comparable runs\" | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($run_details|s$=\"Annual coverage\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | where sport=\"Run\" | eval cadence_factor=case($cadence_units|s$=\"Strides/min\",2,$cadence_units|s$=\"Steps/min\",1,true(),null()) | eval pace_ok=if(pace_valid=1 AND distance_m>0 AND moving_time_s>0,1,0), cadence_ok=if(duration_valid=1 AND moving_time_s>0 AND average_cadence>0 AND isnotnull(cadence_factor),1,0) | stats count AS activities sum(pace_ok) AS pace_activities sum(cadence_ok) AS cadence_activities BY local_year | eval cadence_coverage_pct=round(100*cadence_activities/activities,1), pace_coverage_pct=round(100*pace_activities/activities,1) | sort local_year | where $run_details|s$=\"Annual coverage\" ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period (Year grain uses history)",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "dataSources": {
        "primary": "sport_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "gear": {
      "type": "input.dropdown",
      "title": "Gear",
      "dataSources": {
        "primary": "gear_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "gear",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "quality_mode": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "grain": {
      "type": "input.dropdown",
      "title": "Time grain",
      "options": {
        "token": "grain",
        "defaultValue": "Year",
        "items": [
          {
            "label": "Week",
            "value": "Week"
          },
          {
            "label": "Month",
            "value": "Month"
          },
          {
            "label": "Year",
            "value": "Year"
          }
        ]
      }
    },
    "history_scope": {
      "type": "input.dropdown",
      "title": "Annual scope",
      "options": {
        "token": "history_scope",
        "defaultValue": "Full years",
        "items": [
          {
            "label": "Full years",
            "value": "Full years"
          },
          {
            "label": "Comparable YTD",
            "value": "Comparable YTD"
          }
        ]
      }
    },
    "split": {
      "type": "input.dropdown",
      "title": "Group series",
      "options": {
        "token": "split",
        "defaultValue": "Sport",
        "items": [
          {
            "label": "Total",
            "value": "Total"
          },
          {
            "label": "Sport",
            "value": "Sport"
          },
          {
            "label": "Gear",
            "value": "Gear"
          }
        ]
      }
    },
    "cadence_units": {
      "type": "input.dropdown",
      "title": "CSV cadence convention",
      "options": {
        "token": "cadence_units",
        "defaultValue": "Unconfirmed",
        "items": [
          {
            "label": "Unconfirmed",
            "value": "Unconfirmed"
          },
          {
            "label": "Strides/min",
            "value": "Strides/min"
          },
          {
            "label": "Steps/min",
            "value": "Steps/min"
          }
        ]
      }
    },
    "performance": {
      "type": "input.dropdown",
      "title": "Metric \u00b7 performance",
      "dataSources": {
        "primary": "performance_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"metric_id\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "performance",
        "defaultValue": "__auto__",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "effort_target": {
      "type": "input.dropdown",
      "title": "Best-effort target",
      "dataSources": {
        "primary": "effort_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "effort_target",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "run_details": {
      "type": "input.dropdown",
      "title": "Comparable runs / annual coverage",
      "options": {
        "token": "run_details",
        "defaultValue": "Comparable runs",
        "items": [
          {
            "label": "Comparable runs",
            "value": "Comparable runs"
          },
          {
            "label": "Annual coverage",
            "value": "Annual coverage"
          }
        ]
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {
        "item": "viz_0",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 360
        }
      },
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 360,
          "w": 1200,
          "h": 360
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 0,
          "y": 720,
          "w": 1200,
          "h": 360
        }
      }
    ],
    "globalInputs": [
      "time",
      "snapshot",
      "sport",
      "gear",
      "quality_mode",
      "units",
      "grain",
      "history_scope",
      "split",
      "cadence_units",
      "performance",
      "effort_target",
      "run_details"
    ]
  }
}
